"""Hosted identifiers exposed by automatically emitted platform headers.

This deterministic union was audited from the Darwin 26.5 SDK and the Nix
x86_64-linux glibc 2.42 / Linux 6.18 headers used by the supported build
matrix.  It covers the POSIX headers imported by ``src/stdlib`` plus btrc's
native GPU, GUI, and tray headers.  User-requested headers remain an explicit
C-interop seam rather than silently depending on the compiler host.
"""


def _names(text: str) -> frozenset[str]:
    return frozenset(text.split())


