# Only ordinary typedef names collide with source typedef declarations.  The
# broader set above also contains struct/union tags (for example ``tm`` and
# ``timespec``), which live in a separate C namespace and remain legal source
# identifiers.  POSIX/native typedefs are conventionally ``*_t`` plus this
# small audited set of public aliases and callback types.
_HOSTED_PLATFORM_TYPEDEF_ALIASES = _names("""
BtrcGPUAsync BtrcGPUAsyncResultRelease BtrcGPUAsyncWaitOutcome DIR
btrc_font_draw_fn btrc_font_height_fn btrc_font_width_fn
btrc_gpu_destroy_compute_candidate_fn u_char u_int u_long u_short uint ulong
ushort
""")
HOSTED_PLATFORM_TYPEDEF_NAMES = (
    frozenset(name for name in HOSTED_PLATFORM_TYPE_NAMES if name.endswith("_t")) | _HOSTED_PLATFORM_TYPEDEF_ALIASES
)

